window.RP_SESSION={"id":"S-0899a146a84c","messages":[{"id":"RP-0251093","time":"2026-08-27T00:58:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-6ba6a097816f"]},{"id":"RP-0251094","time":"2026-08-27T00:58:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'올리브'의 민첩 판정 :\n[2] + [2] = [4]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0251095","time":"2026-08-27T00:59:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 토르번과 에스텔이 대화하고 있었을 때, 올리브는 뒷담 아닌 뒷담이 까이는 줄도 모른 채 머리카락을 깎고 있었습니다.","characters":["P-6ba6a097816f"]},{"id":"RP-0251096","time":"2026-08-27T01:01:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 사각. 사각. 달빛에서도 반짝거리는 백색 머리카락들이 잘러 나갑니다. 머릿결이 상했으니, 어쩔 수 없죠.","characters":["P-6ba6a097816f"]},{"id":"RP-0251097","time":"2026-08-27T01:02:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 간질간질, 흉터진 곳이 가려웠습니다. 정확히 말하자면, 흉터와 맨살의 경계, 특히 살갗이 우글우글 한 곳이요. 올리브는 거리낌 없이 가려운 곳을 긁었습니다. 그야, 그것이 편한 걸요.","characters":["P-6ba6a097816f"]},{"id":"RP-0251098","time":"2026-08-27T01:05:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 스카일라의 치료사들은 그렇게 하면 흉터가 더 심하게 남을 거라 이야기 했지만, 올리브에게 신경 쓰이는 일이 아니었습니다. 외모야 중요한 것은 아닙니다. 올리브가 탄 머리카락을 자르는 것은 바보 같이 보이고 싶지 않기 때문입니다. 더이상 예뻐 보이고 싶은 사람은 없는걸요. 그 이후로, 줄곧.","characters":["P-6ba6a097816f"]},{"id":"RP-0251099","time":"2026-08-27T01:06:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 사각. 사각.","characters":["P-6ba6a097816f"]},{"id":"RP-0251100","time":"2026-08-27T01:06:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아, 다 잘라 내었습니다.","characters":["P-6ba6a097816f"]},{"id":"RP-0251101","time":"2026-08-27T01:07:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6ba6a097816f"]},{"id":"RP-0251102","time":"2026-08-27T01:07:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
